const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageBreak, Header, Footer, PageNumber, TabStopType,
  TabStopPosition
} = require('docx');

// Color palette (Luxora premium feel: deep teal, warm gold, soft neutrals)
const TEAL = "1F4E5C";
const GOLD = "B8945F";
const SLATE = "3D4852";
const SAND = "F5EFE6";
const ASH = "E8E2D7";

// Helpers
const border = { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };

const P = (text, opts = {}) => new Paragraph({
  spacing: { after: 120 },
  ...opts,
  children: Array.isArray(text)
    ? text
    : [new TextRun({ text, size: 22, font: "Calibri", ...(opts.runOpts || {}) })]
});

const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 200 },
  children: [new TextRun({ text, size: 36, bold: true, color: TEAL, font: "Calibri" })]
});

const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 280, after: 160 },
  children: [new TextRun({ text, size: 28, bold: true, color: TEAL, font: "Calibri" })]
});

const H3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  spacing: { before: 200, after: 100 },
  children: [new TextRun({ text, size: 24, bold: true, color: SLATE, font: "Calibri" })]
});

const Bullet = (text, bold = false) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 80 },
  children: typeof text === "string"
    ? [new TextRun({ text, size: 22, font: "Calibri", bold })]
    : text
});

const SubBullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 1 },
  spacing: { after: 60 },
  children: [new TextRun({ text, size: 22, font: "Calibri" })]
});

const Numbered = (text, ref = "numbered") => new Paragraph({
  numbering: { reference: ref, level: 0 },
  spacing: { after: 100 },
  children: typeof text === "string"
    ? [new TextRun({ text, size: 22, font: "Calibri" })]
    : text
});

const Spacer = () => new Paragraph({ children: [new TextRun({ text: "" })], spacing: { after: 100 } });

const PullQuote = (text) => new Paragraph({
  spacing: { before: 200, after: 200 },
  alignment: AlignmentType.LEFT,
  border: {
    left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 12 }
  },
  indent: { left: 360 },
  children: [new TextRun({ text, size: 24, italics: true, color: SLATE, font: "Calibri" })]
});

// Table cell helper
const Cell = (text, opts = {}) => new TableCell({
  borders,
  width: { size: opts.width || 4680, type: WidthType.DXA },
  shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
  margins: { top: 120, bottom: 120, left: 160, right: 160 },
  children: [new Paragraph({
    children: [new TextRun({
      text,
      size: opts.size || 20,
      bold: opts.bold || false,
      color: opts.color || "000000",
      font: "Calibri"
    })]
  })]
});

// Title page
const titlePage = [
  new Paragraph({ children: [new TextRun({ text: "" })], spacing: { before: 2400 } }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 },
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 28, bold: true, color: GOLD, font: "Calibri", characterSpacing: 60 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 },
    children: [new TextRun({ text: "Internal Strategy Document", size: 20, color: SLATE, italics: true, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 },
    children: [new TextRun({ text: "The Luxora AI Architecture", size: 56, bold: true, color: TEAL, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 800 },
    children: [new TextRun({ text: "A Segmented AI Coaching System for Independent Med Spas", size: 28, color: SLATE, italics: true, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 },
    children: [new TextRun({ text: "Course Curriculum, Client Deliverables, and Lineup Expansion", size: 22, color: SLATE, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 1200 },
    children: [new TextRun({ text: "Prepared by: Bethany, Co-Founder & CEO", size: 20, color: SLATE, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 200 },
    children: [new TextRun({ text: "April 2026", size: 20, color: SLATE, font: "Calibri" })]
  }),
  new Paragraph({ children: [new PageBreak()] })
];

// Executive summary
const execSummary = [
  H1("Executive Summary"),
  P("Koru & Ivy built a defensible AI moat in the salon and beauty space by doing one thing right: they segmented coaching into five specialized bots, each anchored by a Brand Context Sheet generated during onboarding. The result is hyper-personalized strategy at scale, delivered through a tiered membership."),
  P("This document adapts that architecture for the medical spa industry and translates it into a Luxora course Bethany and the team can run inside the existing 90-day roadmap. It also identifies five additions to the Luxora lineup that, combined with the AI layer, create a system Koru & Ivy cannot replicate without years of clinical and regulatory training data."),
  Spacer(),
  H3("What Luxora gets from this build"),
  Bullet("A new client-facing course module that fits inside the existing 90-day roadmap without adding meeting hours"),
  Bullet("Five specialized AI agents trained on Luxora methodology and med spa specifics, each tied to a pillar Bethany already teaches"),
  Bullet("A Med Spa Context Matrix that becomes the first deliverable of every engagement and replaces the generic intake form"),
  Bullet("Five lineup additions that turn the AI layer into a recurring revenue product, not a one-time setup"),
  Bullet("A defensible position against Koru & Ivy and any imitator entering the med spa space"),
  new Paragraph({ children: [new PageBreak()] })
];

// Section 1: Why this matters
const section1 = [
  H1("Section 1: Why This Architecture Wins"),
  P("Most AI tools fail in service businesses for the same reason: context dilution. A single chatbot asked to write captions, audit ads, and coach sales reads as generic because its instructions are pulled in five directions at once. Owners try it twice, get platitudes, and stop using it."),
  P("Koru & Ivy solved this with two design decisions:"),
  Spacer(),
  H3("Design Decision 1: Segment the bots by job"),
  P("Five separate Custom GPTs, each with a narrow specialty. The Content Director does not give CEO advice. The CEO Coach does not write captions. Every bot stays inside its lane, which keeps output sharp."),
  Spacer(),
  H3("Design Decision 2: Front-load context with a Brand Context Sheet"),
  P("During onboarding, the user dictates answers to roughly 73 questions covering brand voice, services, target audience psychology, and local market nuances. The AI synthesizes this into a structured document. Before any bot conversation, the user pastes this sheet into the chat."),
  P("The result: every output is brand-specific from the first message, not after five rounds of correction."),
  PullQuote("\"Leaning harder into fear-based education and authority is your biggest opportunity.\" That output only makes sense if the AI already knows the brand position. Without context, the same prompt produces a generic list of trending audios."),
  Spacer(),
  H3("Why this matters for med spa specifically"),
  P("Med spas have layers of context that beauty salons do not. Device ROI math, FDA compliance language for Botox and filler ads, HIPAA in DM conversations, scope of practice differences between RNs and NPs, regulated state vs unregulated state advertising rules, GLP-1 telehealth referral structures. A generic AI coach will hallucinate on every one of these."),
  P("This is where Luxora has a structural advantage. Bethany already teaches the clinical, regulatory, and operational layers Koru & Ivy cannot. Encoding those layers into the AI is the moat."),
  new Paragraph({ children: [new PageBreak()] })
];

// Section 2: The course
const section2 = [
  H1("Section 2: The Luxora AI Architecture Course"),
  P("This course slots into the existing 90-day roadmap. It does not replace any of the six biweekly calls. It runs as an asynchronous module set that clients work through between calls, with the deliverables reviewed live."),
  Spacer(),
  H3("Course structure at a glance"),
  P("Six modules, mapped to the six biweekly calls. Each module produces one deliverable that feeds the next. The full system is live by Day 60 and refined by Day 90."),
  Spacer(),

  // Module table
  new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [1080, 2400, 3000, 2880],
    rows: [
      new TableRow({
        tableHeader: true,
        children: [
          Cell("Module", { width: 1080, fill: TEAL, color: "FFFFFF", bold: true, size: 20 }),
          Cell("Title", { width: 2400, fill: TEAL, color: "FFFFFF", bold: true, size: 20 }),
          Cell("Maps to Pillar", { width: 3000, fill: TEAL, color: "FFFFFF", bold: true, size: 20 }),
          Cell("Deliverable Produced", { width: 2880, fill: TEAL, color: "FFFFFF", bold: true, size: 20 })
        ]
      }),
      new TableRow({ children: [
        Cell("1", { width: 1080, fill: SAND, bold: true }),
        Cell("Foundation: The Med Spa Context Matrix", { width: 2400 }),
        Cell("Revenue Leak Audit, Market Blueprint", { width: 3000 }),
        Cell("Completed Context Matrix", { width: 2880 })
      ]}),
      new TableRow({ children: [
        Cell("2", { width: 1080, fill: SAND, bold: true }),
        Cell("The Content Director Bot", { width: 2400 }),
        Cell("Reputation Engine, Marketing", { width: 3000 }),
        Cell("90-day content calendar", { width: 2880 })
      ]}),
      new TableRow({ children: [
        Cell("3", { width: 1080, fill: SAND, bold: true }),
        Cell("The Meta Ads Strategist Bot", { width: 2400 }),
        Cell("Marketing, Lead Generation", { width: 3000 }),
        Cell("Audit + creative briefs for active campaigns", { width: 2880 })
      ]}),
      new TableRow({ children: [
        Cell("4", { width: 1080, fill: SAND, bold: true }),
        Cell("The Setter Coach Bot", { width: 2400 }),
        Cell("Staff Sales Training, AI Follow-Up", { width: 3000 }),
        Cell("DM script library + objection responses", { width: 2880 })
      ]}),
      new TableRow({ children: [
        Cell("5", { width: 1080, fill: SAND, bold: true }),
        Cell("The Consult Closer Bot", { width: 2400 }),
        Cell("Staff Sales Training, Package Architecture", { width: 3000 }),
        Cell("Consult script + post-mortem framework", { width: 2880 })
      ]}),
      new TableRow({ children: [
        Cell("6", { width: 1080, fill: SAND, bold: true }),
        Cell("The CEO Coach Bot", { width: 2400 }),
        Cell("LTV Frameworks, Membership, Partnerships", { width: 3000 }),
        Cell("12-month revenue model + capacity plan", { width: 2880 })
      ]})
    ]
  }),
  Spacer(),
  Spacer(),
  P("The next pages break each module down with the specific learning objective, the bot training inputs, the client homework, and how it connects to existing Luxora playbooks.", { runOpts: { italics: true, color: SLATE } }),
  new Paragraph({ children: [new PageBreak()] })
];

// Module details
const moduleDetail = (num, title, learning, botInputs, homework, connects, time) => [
  H2(`Module ${num}: ${title}`),
  H3("Learning objective"),
  P(learning),
  H3("Bot training inputs (what Luxora loads into the GPT)"),
  ...botInputs.map(b => Bullet(b)),
  H3("Client homework"),
  ...homework.map(h => Numbered(h, `m${num}list`)),
  H3("How this connects to existing Luxora deliverables"),
  P(connects),
  H3("Estimated client time"),
  P(time, { runOpts: { italics: true } }),
  Spacer()
];

const module1 = moduleDetail(
  1,
  "Foundation: The Med Spa Context Matrix",
  "The client produces a structured document that captures every piece of context the AI bots need to produce med spa specific output. This replaces the generic intake form Luxora currently uses and becomes the single source of truth for the engagement.",
  [
    "Luxora seven pillar framework as the structural backbone",
    "Med spa specific question set covering: ownership structure, medical director relationship, scope of practice by state, device inventory and ROI, service mix and margin, current marketing channels, sales process, staff structure, current LTV, current churn, regulatory exposure",
    "Brand voice extraction protocol modeled on the Verbal Fingerprint method already used internally",
    "Local market intelligence prompt to capture competitor landscape and demographic positioning"
  ],
  [
    "Complete the 85 question Med Spa Context Matrix via voice dictation (90 minutes recommended)",
    "Upload last 90 days of P&L, last 30 days of CRM lead data, and last 10 ad creatives if running paid",
    "Record a 10 minute voice memo describing their ideal client and how they want their business to feel"
  ],
  "This module replaces the current intake call prep packet. The Context Matrix becomes Appendix A of the Statement of Work. It feeds directly into the Revenue Leak Audit and the Market Blueprint, eliminating the 4 to 6 hours Bethany currently spends translating intake answers into strategy.",
  "90 to 120 minutes of focused work, completed before Call 1."
);

const module2 = moduleDetail(
  2,
  "The Content Director Bot",
  "The client uses a specialized GPT to produce 90 days of on-brand, premium-positioned content without writing from scratch. This module trains them on the prompting structure that turns the bot from a caption generator into a content strategist.",
  [
    "Luxora content pillar framework (the seven strategic pillars Bethany teaches)",
    "Med spa specific compliance rules: before/after image standards, FDA brand name restrictions for injectables, testimonial substantiation requirements",
    "Premium positioning principles: authority-building content, fear-busting education, transformation storytelling without cheap before/after dependence",
    "Bethany's Verbal Fingerprint extracted from the existing sales call transcript",
    "The eight content format blueprints already built into the Luxora AI Content Studio"
  ],
  [
    "Paste the Context Matrix and request 30 reel concepts using the Premium Authority framework",
    "Generate one full week of captions across all eight formats and review with team",
    "Build a 90-day content calendar tied to the practice's slow seasons, device promotion windows, and membership push periods"
  ],
  "Pairs with the Reputation Engine Playbook and the existing Luxora AI Content Studio. The bot becomes the front-end interface clients use; the Content Studio remains the internal Luxora team tool. This is where the existing podcast question review and Verbal Fingerprint work pay off as training data.",
  "60 minutes per week for the first three weeks, then maintenance only."
);

const module3 = moduleDetail(
  3,
  "The Meta Ads Strategist Bot",
  "The client gets a 24/7 paid media co-pilot that audits campaigns, rewrites ad copy, and diagnoses lead quality issues. For non-Jacques accounts, this gives clients a way to spot problems between agency reports.",
  [
    "Meta compliance rules specific to aesthetics: special ad category requirements, before/after restrictions, body part targeting limits",
    "Med spa benchmark CPL, CTR, CPA, and ROAS by service category (injectables vs body vs membership)",
    "Jacques' diagnostic framework for separating traffic problems from creative problems from offer problems",
    "The Luxora pre-qualification copy framework that filters tire-kickers before they book consults",
    "Current algorithm best practices for service-area businesses with single physical location"
  ],
  [
    "Run a full audit of the last 30 days of campaigns using the bot's diagnostic prompt",
    "Generate three creative brief variations for the next launch using the bot, then submit to Jacques or their agency for production",
    "Build a quarterly ad testing roadmap that aligns with seasonal demand and device promotion calendar"
  ],
  "Sits next to Jacques' work for paid clients and replaces the need for clients without paid services to hire a separate agency for creative direction. Pairs with the Laser ROI Playbook when device-specific campaigns are running.",
  "45 minutes per week during active campaigns."
);

const module4 = moduleDetail(
  4,
  "The Setter Coach Bot",
  "The client and their front desk team get line-by-line coaching on every DM and text conversation that loses a lead. This is the bot most likely to produce immediate revenue, because most med spas leak 30 to 50 percent of inbound leads in DMs.",
  [
    "High-ticket sales psychology: micro-commitments, emotional mirroring, the feminine funnel framework already taught at Luxora",
    "Med spa specific objection patterns: price shock on packages, fear of looking unnatural, concerns about downtime, comparison shopping with cheaper providers",
    "HIPAA-aware DM language that builds trust without making medical claims",
    "Bethany's existing DM templates and Aanchal's outreach voice as training examples of what good looks like",
    "The 12 most common DM mistakes Luxora has documented across audits"
  ],
  [
    "Submit five recent DM conversations that did not convert and run the post-mortem prompt",
    "Generate rewritten versions and use them as the team's new template library",
    "Train every front desk staff member on the three highest-leverage rewrites in the next team meeting"
  ],
  "Direct extension of the existing Discovery Call Script work and the feminine funnel methodology. Pairs with the AI Follow-Up systems already installed via GHL. The bot trains the humans; GHL handles the volume.",
  "30 minutes per week, primarily done by the front desk lead."
);

const module5 = moduleDetail(
  5,
  "The Consult Closer Bot",
  "The owner and lead injector get post-mortem coaching on every consult that fails to close. The bot identifies the precise moment the sale was lost and rewrites the consult line by line.",
  [
    "The Luxora consult framework already taught in Staff Sales Training",
    "Premium pricing psychology: package framing, financing presentation, payment plan choreography",
    "Clinical confidence language: how providers can speak with authority without making outcome guarantees",
    "Common closing failures specific to med spa: the soft retreat after price, the over-explanation of mechanism, the missed assumptive close after a yes signal",
    "The Confidential Experience Assessment framework so the bot can simulate a secret shopper review"
  ],
  [
    "Submit transcripts or detailed notes from three consults that did not convert in the last 30 days",
    "Run the post-mortem and rewrite prompt on each",
    "Roleplay the rewritten version with a team member before the next live consult"
  ],
  "Pairs with the existing Staff Sales Training, the Discovery Call Script, and the Confidential Experience Assessment. The bot becomes the always-on extension of the live training, so skills do not decay between Luxora calls.",
  "45 minutes per week during active sales coaching, then on-demand."
);

const module6 = moduleDetail(
  6,
  "The CEO Coach Bot",
  "The owner gets a fractional COO and CMO available 24/7 for revenue modeling, capacity planning, hiring decisions, and strategic positioning questions. This is the highest-tier bot and stays inside the Luxora top tier offer.",
  [
    "The Luxora capacity planning framework: provider hours, treatment room utilization, average ticket math, membership penetration",
    "Device ROI calculators specific to the major capital equipment categories (laser, body contouring, microneedling, energy-based devices)",
    "Hiring scorecards for medical director, lead injector, esthetician, front desk lead, marketing coordinator",
    "The Luxora partnership framework for OB-GYN, dermatology, plastics, and concierge medicine referral relationships",
    "LTV modeling that accounts for membership compounding, package laddering, and referral economics"
  ],
  [
    "Run the 12-month revenue model prompt using current numbers from the Context Matrix",
    "Build a capacity plan that shows what the practice looks like at the next revenue tier",
    "Submit one strategic question per week (hiring, expansion, pricing, equipment) and use the bot's response as the agenda for the next Luxora call"
  ],
  "Pairs with the existing KPI Reference Playbook, the 90 Day Celebration Event Playbook, and the LTV Framework. The bot extends Bethany's strategic thinking into the days between calls, which is the single biggest gap clients currently raise.",
  "30 to 60 minutes per week, owner-only."
);

const moduleDetails = [
  ...module1, new Paragraph({ children: [new PageBreak()] }),
  ...module2, new Paragraph({ children: [new PageBreak()] }),
  ...module3, new Paragraph({ children: [new PageBreak()] }),
  ...module4, new Paragraph({ children: [new PageBreak()] }),
  ...module5, new Paragraph({ children: [new PageBreak()] }),
  ...module6, new Paragraph({ children: [new PageBreak()] })
];

// Section 3: Mapping to existing deliverables
const section3 = [
  H1("Section 3: How This Maps to Existing Luxora Deliverables"),
  P("Nothing in the existing lineup goes away. The AI architecture sits underneath what Luxora already delivers and makes it stick between calls. Here is the full crosswalk:"),
  Spacer(),

  new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [
      new TableRow({
        tableHeader: true,
        children: [
          Cell("Existing Luxora Deliverable", { width: 4680, fill: TEAL, color: "FFFFFF", bold: true }),
          Cell("AI Layer Connection", { width: 4680, fill: TEAL, color: "FFFFFF", bold: true })
        ]
      }),
      new TableRow({ children: [
        Cell("Revenue Leak Audit", { width: 4680, fill: SAND }),
        Cell("Context Matrix replaces the intake form and feeds the audit directly", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Market Blueprint", { width: 4680, fill: SAND }),
        Cell("Context Matrix provides local market data; CEO Coach Bot pressure-tests the blueprint", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Statement of Work", { width: 4680, fill: SAND }),
        Cell("Context Matrix becomes Appendix A; AI access tier defined in scope", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Membership Playbook", { width: 4680, fill: SAND }),
        Cell("CEO Coach Bot runs membership penetration and compounding LTV models", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Package and Upsell Playbook", { width: 4680, fill: SAND }),
        Cell("Consult Closer Bot drills package presentation; CEO Coach models margin", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Reputation Engine Playbook", { width: 4680, fill: SAND }),
        Cell("Content Director Bot generates the 90 day calendar that powers the engine", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Laser ROI Playbook", { width: 4680, fill: SAND }),
        Cell("CEO Coach calculates device ROI; Meta Ads Bot builds device-specific campaigns", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Partnership Framework", { width: 4680, fill: SAND }),
        Cell("CEO Coach Bot scripts partnership outreach and models referral economics", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("90 Day Celebration Event Playbook", { width: 4680, fill: SAND }),
        Cell("Content Director Bot produces the full event content arc", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Team Kickoff Playbook", { width: 4680, fill: SAND }),
        Cell("Setter Coach and Consult Closer become ongoing team training tools", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Discovery Call Script", { width: 4680, fill: SAND }),
        Cell("Consult Closer Bot is trained on the script and reinforces it weekly", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Confidential Experience Assessment", { width: 4680, fill: SAND }),
        Cell("Consult Closer Bot uses the framework to simulate ongoing secret shopper reviews", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("KPI Reference Playbook", { width: 4680, fill: SAND }),
        Cell("CEO Coach Bot pulls KPIs into weekly diagnostics and flags drift", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Bi-weekly Call Checklist", { width: 4680, fill: SAND }),
        Cell("Bot outputs become the agenda for each call, eliminating prep time", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Luxora AI Content Studio", { width: 4680, fill: SAND }),
        Cell("Internal team tool; the Content Director Bot is the client-facing version", { width: 4680 })
      ]}),
      new TableRow({ children: [
        Cell("Feminine Funnel Master Doc", { width: 4680, fill: SAND }),
        Cell("Setter Coach Bot trained on the framework, applies it to live DMs", { width: 4680 })
      ]})
    ]
  }),
  new Paragraph({ children: [new PageBreak()] })
];

// Section 4: Gaps and additions
const section4 = [
  H1("Section 4: What to Add to the Lineup"),
  P("The AI architecture is the unlock, but it surfaces five gaps in the current lineup that, once filled, turn Luxora into a category of one. Each addition is sized, priced, and tied to the existing methodology."),
  Spacer(),

  H2("Addition 1: The Med Spa Context Matrix as a Standalone Product"),
  H3("What it is"),
  P("A productized version of Module 1 sold as an entry-level diagnostic. Owner completes the 85 question intake, Luxora delivers a 25 page Context Matrix document plus a 60 minute review call. No commitment to the full engagement."),
  H3("Why it matters"),
  P("Currently the only way into Luxora is the full done-with-you engagement. That is the right top of funnel for the right client, but it leaves money on the table for owners who are not yet ready and partners who want to refer their list without sending them into a six-figure conversation. The Context Matrix becomes the on-ramp."),
  H3("Pricing and positioning"),
  P("Recommended price: $2,500 to $3,500. Position as \"the strategic diagnostic that most med spa consultants charge $15k for.\" Roughly 30 to 40 percent of buyers should convert into the full engagement within 90 days based on comparable diagnostic-to-engagement conversion in adjacent industries."),
  H3("Effort to build"),
  P("Two weeks. The question set already exists in fragments across the current intake materials. Aanchal can run the first draft and Bethany refines."),
  Spacer(),

  H2("Addition 2: The Luxora AI Suite as a Recurring Subscription"),
  H3("What it is"),
  P("All five Custom GPTs plus the Context Matrix update tool, sold as a monthly subscription to Luxora alumni and to Context Matrix buyers who do not enter the full engagement. Includes quarterly bot updates and a private community channel for prompt sharing."),
  H3("Why it matters"),
  P("Right now, when a client finishes the 90 day engagement, the relationship goes dormant unless they renew. The AI Suite is the bridge that keeps them inside the Luxora ecosystem and produces predictable monthly revenue. It also creates a graduation path so alumni do not leak to Koru & Ivy or competitors."),
  H3("Pricing and positioning"),
  P("Recommended price: $497 to $797 per month. Tier 1 (Content Director plus Meta Ads) at the low end, Tier 2 (adds Setter Coach and Consult Closer) in the middle, Tier 3 (full suite plus CEO Coach plus quarterly strategy call with Bethany) at the top. Mirrors Koru & Ivy's tier logic but anchored in clinical specifics they cannot match."),
  H3("Effort to build"),
  P("Six to eight weeks for the bot training and platform setup. Jacques can lead the technical build; Bethany owns the prompt engineering. The Verbal Fingerprint and Content Studio work already done covers roughly 40 percent of the training data."),
  Spacer(),

  H2("Addition 3: The Compliance Layer (Luxora's Defensible Moat)"),
  H3("What it is"),
  P("A regulated-content review system layered on top of every bot output. The bot flags any output that may violate FDA injectable advertising rules, state scope of practice limits, or HIPAA. This is the single feature Koru & Ivy cannot copy without years of medical-specific training data."),
