{"language": "javascript", "code": "const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageBreak, Header, Footer, PageNumber, TabStopType,
  TabStopPosition
} = require('docx');

// Color palette (Luxora premium feel: deep teal, warm gold, soft neutrals)
const TEAL = "1F4E5C";
const GOLD = "B8945F";
const SLATE = "3D4852";
const SAND = "F5EFE6";
const ASH = "E8E2D7";

// Helpers
const border = { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };

const P = (text, opts = {}) => new Paragraph({
  spacing: { after: 120 },
  ...opts,
  children: Array.isArray(text)
    ? text
    : [new TextRun({ text, size: 22, font: "Calibri", ...(opts.runOpts || {}) })]
});

const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 200 },
  children: [new TextRun({ text, size: 36, bold: true, color: TEAL, font: "Calibri" })]
});

const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 280, after: 160 },
  children: [new TextRun({ text, size: 28, bold: true, color: TEAL, font: "Calibri" })]
});

const H3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  spacing: { before: 200, after: 100 },
  children: [new TextRun({ text, size: 24, bold: true, color: SLATE, font: "Calibri" })]
});

const Bullet = (text, bold = false) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 80 },
  children: typeof text === "string"
    ? [new TextRun({ text, size: 22, font: "Calibri", bold })]
    : text
});

const SubBullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 1 },
  spacing: { after: 60 },
  children: [new TextRun({ text, size: 22, font: "Calibri" })]
});

const Numbered = (text, ref = "numbered") => new Paragraph({
  numbering: { reference: ref, level: 0 },
  spacing: { after: 100 },
  children: typeof text === "string"
    ? [new TextRun({ text, size: 22, font: "Calibri" })]
    : text
});

const Spacer = () => new Paragraph({ children: [new TextRun({ text: "" })], spacing: { after: 100 } });

const PullQuote = (text) => new Paragraph({
  spacing: { before: 200, after: 200 },
  alignment: AlignmentType.LEFT,
  border: {
    left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 12 }
